package messaging

import (
	"encoding/base32"
	"errors"
	"strings"
)

// MessageID is the internal identifier of a message: the UUIDv7 primary key generated by
// PostgreSQL (decision log §18, G1-1).
type MessageID [16]byte

// messageIDPrefix starts every public message ID.
const messageIDPrefix = "msg_"

// publicIDEncoding is Crockford's base32 alphabet without padding: 16 bytes become 26 characters.
// ParseMessageID accepts only the canonical form, so each message has exactly one public ID.
var publicIDEncoding = base32.NewEncoding("0123456789ABCDEFGHJKMNPQRSTVWXYZ").WithPadding(base32.NoPadding)

// ErrInvalidMessageID is returned by ParseMessageID.
var ErrInvalidMessageID = errors.New("invalid message ID")

// String returns the opaque public form of id (contract MessageId), for example
// msg_068FQ0JZ8X1Q2T7N5M4K3J2H1G.
func (id MessageID) String() string { return messageIDPrefix + publicIDEncoding.EncodeToString(id[:]) }

// ParseMessageID parses the public form of a message ID.
func ParseMessageID(s string) (MessageID, error) {
	encoded, ok := strings.CutPrefix(s, messageIDPrefix)
	if !ok || len(encoded) != 26 {
		return MessageID{}, ErrInvalidMessageID
	}
	b, err := publicIDEncoding.DecodeString(encoded)
	if err != nil || len(b) != 16 || publicIDEncoding.EncodeToString(b) != encoded {
		return MessageID{}, ErrInvalidMessageID
	}
	var id MessageID
	copy(id[:], b)
	return id, nil
}
